def calcular_desconto(preco: float, percentual: float) -> float:
    """Calcula o preço final aplicando um desconto percentual.

    Args:
        preco: preço original, deve ser positivo.
        percentual: percentual de desconto, entre 0 e 100.

    Raises:
        ValueError: se `preco` for negativo ou `percentual` estiver fora de [0, 100].
    """
    if preco < 0:
        raise ValueError("preco não pode ser negativo")
    if not (0 <= percentual <= 100):
        raise ValueError("percentual deve estar entre 0 e 100")
    return preco * (1 - percentual / 100)

