import pytest

from calculadora_desconto import calcular_desconto


def test_calcula_desconto_valido():
    assert calcular_desconto(100.0, 10) == 90.0


def test_preco_negativo_levanta_erro():
    with pytest.raises(ValueError):
        calcular_desconto(-10.0, 10)


def test_percentual_fora_do_intervalo_levanta_erro():
    with pytest.raises(ValueError):
        calcular_desconto(100.0, 150)
